package io.github.borderarea01.znote;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import java.io.*;

final class GlitchAppearanceSmoke {
    final Instrumentation test;final Context context;final UiAutomation ui;
    GlitchAppearanceSmoke(Instrumentation test){this.test=test;context=test.getTargetContext();ui=test.getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);}
    void check(boolean result,String message){if(!result)throw new AssertionError(message);}
    void shell(String command)throws Exception{try(ParcelFileDescriptor fd=ui.executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
    AccessibilityNodeInfo find(AccessibilityNodeInfo n,String value){if(n==null)return null;if(value.equals(String.valueOf(n.getText()))||value.equals(String.valueOf(n.getContentDescription())))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i),hit=find(child,value);if(hit!=null){if(child!=hit)child.recycle();return hit;}if(child!=null)child.recycle();}return null;}
    AccessibilityNodeInfo node(String value)throws Exception{for(int i=0;i<100;i++){for(AccessibilityWindowInfo window:ui.getWindows()){AccessibilityNodeInfo root=window.getRoot(),hit=find(root,value);if(root!=null&&root!=hit)root.recycle();if(hit!=null)return hit;}Thread.sleep(70);}throw new Exception("Missing "+value);}
    void tap(String value)throws Exception{AccessibilityNodeInfo n=node(value);Rect rect=new Rect();n.getBoundsInScreen(rect);n.recycle();long t=SystemClock.uptimeMillis();for(int action:new int[]{0,1}){MotionEvent e=MotionEvent.obtain(t,SystemClock.uptimeMillis(),action,rect.centerX(),rect.centerY(),0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);ui.injectInputEvent(e,true);e.recycle();}Thread.sleep(350);}
    void shot(String name)throws Exception{Thread.sleep(500);Bitmap b=ui.takeScreenshot();try(FileOutputStream out=context.openFileOutput("glitch-"+name+".png",0)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    void set(String style,String mode){context.getContentResolver().call(android.net.Uri.parse("content://"+context.getPackageName()+".capture-session"),"appearance","{\"style\":\""+style+"\",\"mode\":\""+mode+"\"}",null);}
    void launcher(String suffix){Intent intent=context.getPackageManager().getLaunchIntentForPackage(context.getPackageName());check(intent!=null&&intent.getComponent().getClassName().endsWith(suffix),"One correct launcher");check(context.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setPackage(context.getPackageName()),0).size()==1,"Duplicate launchers");}
    String js(MainActivity a,String code)throws Exception{String[] value={null};java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);test.runOnMainSync(()->{try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField("web");f.setAccessible(true);((android.webkit.WebView)f.get(a)).evaluateJavascript(code,v->{value[0]=v;latch.countDown();});}catch(Exception e){value[0]="error";latch.countDown();}});check(latch.await(5,java.util.concurrent.TimeUnit.SECONDS),"WebView callback timeout");return value[0];}
    void run(){Bundle result=new Bundle();try{
        check(Build.MODEL.contains("sdk"),"Isolated emulator only");android.accessibilityservice.AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;ui.setServiceInfo(info);context.getSharedPreferences("ZNoteUpdates",0).edit().putBoolean("auto_check",false).commit();
        context.getSharedPreferences("MainActivity",0).edit().putString("origin","http://10.0.2.2:3747").commit();context.getSharedPreferences("CaptureAuthorization",0).edit().putString(android.net.Uri.encode("http://10.0.2.2:3747"),"zn_"+"0".repeat(64)).commit();
        set("glitch","light");launcher("LauncherGlitch");Intent start=context.getPackageManager().getLaunchIntentForPackage(context.getPackageName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);MainActivity main=(MainActivity)test.startActivitySync(start);node("连接到你的知识库").recycle();shot("connect-light");tap("界面与图标");tap("经典");tap("取消");launcher("LauncherGlitch");
        tap("界面与图标");tap("建筑故障");tap("夜间");node("连接到你的知识库").recycle();shot("connect-dark");launcher("LauncherGlitch");
        context.startActivity(new Intent(context,FloatingShareActivity.class).putExtra(Intent.EXTRA_TEXT,"https://www.pixiv.net/artworks/12345").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));node("保存到知识库").recycle();node("登录 Pixiv").recycle();shot("panel-dark");tap("收起采集面板");
        set("glitch","light");context.startActivity(new Intent(context,FloatingShareActivity.class).putExtra(Intent.EXTRA_TEXT,"https://www.pixiv.net/artworks/12345").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));node("保存到知识库").recycle();shot("panel-light");tap("收起采集面板");
        shell("settings delete secure enabled_accessibility_services");shell("settings put secure enabled_accessibility_services io.github.borderarea01.znote/.CaptureAssistService");shell("settings put secure accessibility_enabled 1");Thread.sleep(1200);tap("ZNote 贴边页签，点击展开，拖动换位置");node("前往知识库").recycle();shot("small-expanded");tap("ZNote 采集面板；点击标题收起，拖动标题可移动");shot("bookmark");
        set("minimal","system");launcher("LauncherClassic");context.startActivity(new Intent(context,FloatingShareActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));node("保存到知识库").recycle();shot("panel-classic");tap("收起采集面板");
        main=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));tap("连接并打开");node("知识库浏览").recycle();String firstPaint=js(main,"document.documentElement.dataset.style");check(org.json.JSONObject.quote("minimal").equals(firstPaint),"Native first paint: "+firstPaint);js(main,"document.body.dataset.draft='kept';ZNoteAppearance.set(JSON.stringify({style:'glitch',mode:'dark'}));true");Thread.sleep(800);check(js(main,"JSON.parse(ZNoteAppearance.snapshot()).style").contains("glitch"),"Web appearance did not update native preference");check(js(main,"document.body.dataset.draft").contains("kept"),"Appearance reloaded the editor");set("minimal","system");
        check("minimal".equals(new org.json.JSONObject(new String(new android.util.AtomicFile(new File(context.getFilesDir(),"appearance.json")).readFully(),java.nio.charset.StandardCharsets.UTF_8)).getString("style")),"Preference did not persist");result.putString("stream","\nZNOTE_GLITCH_APPEARANCE_PASS: native selection/cancel, light/dark panels, Pixiv action, original style restoration, one launcher, persistence and a live WebView bridge without reload\n");test.finish(Activity.RESULT_OK,result);
    }catch(Throwable e){try{shot("failure");}catch(Exception ignored){}result.putString("stream","\nZNOTE_GLITCH_APPEARANCE_FAIL: "+e+"\n");test.finish(Activity.RESULT_CANCELED,result);}}
}
